                        </button>
                    </div>
                )}
            </div>
        </>
    );
}

"use client";

import { useRef } from "react";
import { Product } from "@/types/product";
import ProductCard from "./ProductCard";
import Link from "next/link";

interface CategoryShelfProps {
    title: string;
    products: Product[];
    categorySlug?: string;
}

export default function CategoryShelf({ title, products, categorySlug }: CategoryShelfProps) {
    const scrollRef = useRef<HTMLDivElement>(null);

    const scroll = (direction: 'left' | 'right') => {
        if (scrollRef.current) {
            const { scrollLeft, clientWidth } = scrollRef.current;
            const scrollTo = direction === 'left' ? scrollLeft - clientWidth : scrollLeft + clientWidth;
            scrollRef.current.scrollTo({ left: scrollTo, behavior: 'smooth' });
        }
    };

    return (
        <section className="py-12 bg-white">
            <div className="max-w-[1600px] mx-auto px-4 sm:px-6 lg:px-8">
                {/* Header */}
                <div className="flex items-center justify-between mb-8">
                    <h2 className="text-2xl font-black text-slate-900 tracking-tight">{title}</h2>
                    <div className="flex items-center gap-4">
                        <Link
                            href={`#full-collection`}
                            className="px-4 py-1.5 bg-slate-50 text-slate-600 rounded-full text-[11px] font-bold uppercase  hover:bg-slate-100 transition-all flex items-center gap-2 border border-slate-100"
                        >
                            ดูทั้งหมด
                            <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M9 5l7 7-7 7" />
                            </svg>
                        </Link>

                        {/* Navigation Arrows */}
                        <div className="hidden md:flex items-center gap-2">
                            <button
                                onClick={() => scroll('left')}
                                className="w-8 h-8 rounded-full border border-slate-100 flex items-center justify-center text-slate-400 hover:text-slate-900 hover:border-slate-300 transition-all"
                            >
                                <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 19l-7-7 7-7" />
                                </svg>
                            </button>
                            <button
                                onClick={() => scroll('right')}
                                className="w-8 h-8 rounded-full border border-slate-100 flex items-center justify-center text-slate-400 hover:text-slate-900 hover:border-slate-300 transition-all"
                            >
                                <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M9 5l7 7-7 7" />
                                </svg>
                            </button>
                        </div>
                    </div>
                </div>

                {/* Main Scroll Area */}
                <div
                    ref={scrollRef}
                    className="flex gap-5 overflow-x-auto pb-8 scroll-smooth no-scrollbar"
                    style={{ scrollbarWidth: 'none', msOverflowStyle: 'none' }}
                >
                    {products.map((product) => (
                        <div key={product.id} className="flex-none w-[280px]">
                            <ProductCard product={product} />
                        </div>
                    ))}
                </div>
            </div>

            <style jsx global>{`
                .no-scrollbar::-webkit-scrollbar {
                    display: none;
                }
            `}</style>
        </section>
    );
}

"use client";

import { useEffect, useState } from "react";
import { Product } from "@/types/product";

interface FilterSidebarProps {
    products: Product[];
    onFilterChange: (filters: {
        categories: string[];
        brands: string[];
        priceRange: [number, number];
    }) => void;
    className?: string; // Allow custom styling
}

export default function FilterSidebar({ products, onFilterChange, className = "" }: FilterSidebarProps) {
    const [selectedCategories, setSelectedCategories] = useState<string[]>([]);
    const [selectedBrands, setSelectedBrands] = useState<string[]>([]);
    const [priceRange, setPriceRange] = useState<[number, number]>([0, 100000]); // Default max high enough
    const [isMobileOpen, setIsMobileOpen] = useState(false);

    // Dynamic Data Extraction
    const categories = Array.from(new Set(products.map((p) => p.category))).sort();
    const brands = Array.from(new Set(products.map((p) => p.brand))).filter(Boolean).sort();
    const minPrice = Math.min(...products.map((p) => p.price * 35));
    const maxPrice = Math.max(...products.map((p) => p.price * 35));

    useEffect(() => {
        // Initialize price range based on actual data once
        if (products.length > 0) {
            setPriceRange([0, Math.ceil(maxPrice)]);
        }
    }, [products]); // Run only when products change (initial load)

    // Notify parent of changes
    useEffect(() => {
        onFilterChange({
            categories: selectedCategories,
            brands: selectedBrands,
            priceRange,
        });
    }, [selectedCategories, selectedBrands, priceRange.join(",")]); // Join array to detect value changes

    const toggleCategory = (category: string) => {
        setSelectedCategories((prev) =>
            prev.includes(category)
                ? prev.filter((c) => c !== category)
                : [...prev, category]
        );
    };

    const toggleBrand = (brand: string) => {
        setSelectedBrands((prev) =>
            prev.includes(brand)
                ? prev.filter((b) => b !== brand)
                : [...prev, brand]
        );
    };

