                    </div>

                    {/* Brands */}
                    <div className="mb-8">
                        <h3 className="text-sm font-bold text-slate-900 mb-4">Brands</h3>
                        <div className="space-y-2 max-h-48 overflow-y-auto scrollbar-hide">
